import itertools

def solve_small(n, N):
    # Generate all subsets of {0, ..., n-1}
    subsets = []
    for i in range(1 << n):
        s = set()
        for j in range(n):
            if (i >> j) & 1:
                s.add(j)
        subsets.append(s)

    # We want to find S, T such that |S|=N, |T|=N, S \cap T = \emptyset,
    # and for all s in S, t in T, s \cap t != \emptyset.
    # This is equivalent to finding S of size N such that the number of t
    # that intersect all s in S is at least N, and S and T are disjoint.

    # Try all combinations of S of size N
    import itertools
    for S_indices in itertools.combinations(range(len(subsets)), N):
        S = [subsets[i] for i in S_indices]
        # Find all t that intersect all s in S
        T_candidates = []
        for t in subsets:
            if all(t.intersection(s) for s in S):
                T_candidates.append(t)

        # We need T to be a subset of T_candidates, |T|=N, and S \cap T = \emptyset.
        # So we need |T_candidates \ S| >= N.
        S_sets = set(tuple(sorted(list(s))) for s in S)
        T_candidates_filtered = [t for t in T_candidates if tuple(sorted(list(t))) not in S_sets]

        if len(T_candidates_filtered) >= N:
            return True
    return False

for n in range(1, 6):
    for N in range(1, 10):
        if solve_small(n, N):
            print(f"n={n}, N={N}: Possible")
        else:
            # Since it's monotonic in N, we can stop
            break
